// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 x, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        // roll to an arbitrary block; the rule is stated over all admissible blocks
        uint256 blk = bound(x, 1, 2 ** 250);
        vm.roll(blk);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback should succeed");

        // Universal rule: whenever the payout condition (block.number % 15 == 0) holds,
        // the reference sends its whole balance out, so the contract holds 0 wei.
        // The mutant pays on the complement, so on multiple-of-15 blocks it retains funds.
        if (block.number % 15 == 0) {
            assertTrue(address(c).balance == 0, "balance must be drained on payout blocks");
        } else {
            assertTrue(address(c).balance > 0, "non-payout blocks keep funds");
        }
    }
}
